const url='https://federation.ccdi.cancer.gov/api/v1/sample?library_strategy=RNA-Seq&page=1&per_page=1';
try {
  const res = await fetch(url, {headers:{'accept':'application/json'}});
  const text = await res.text();
  nodeRepl.write(JSON.stringify({ok:res.ok,status:res.status,url:res.url,headers:Object.fromEntries(res.headers.entries()),text:text.slice(0,2000)}, null, 2));
} catch (e) {
  nodeRepl.write(JSON.stringify({error:String(e), stack:e.stack?.split('\n').slice(0,3)}, null, 2));
}

